```
let cursor: string | undefined = undefined;
do {
  const page = await client.listEvents({ createdAfter: since, createdBefore: pollStartedAt, limit: PAGE_SIZE, cursor });
  for (const event of page.data) await handleEvent(invoices, event);
  cursor = page.hasMore ? (page.nextCursor ?? undefined) : undefined;
} while (cursor);
await cursors.set(CURSOR_KEY, pollStartedAt);
```
